<?php
declare(strict_types=1);namespace App\Services;use App\Core\{Auth,Database};final class ScopeService{public function canAccessOrganization(?int $regionId,?int $parkId,?int $areaId):bool{if(Auth::can('tickets.view.all'))return true;if(Auth::can('tickets.view.self')&&!Auth::can('tickets.view.scope'))return false;if(!Auth::can('tickets.view.scope'))return false;$s=Database::pdo()->prepare("SELECT COUNT(*) FROM user_scopes WHERE user_id=? AND ended_at IS NULL AND (scope_type='GLOBAL' OR (scope_type='REGION' AND region_id=?) OR (scope_type='PARK' AND park_id=?) OR (scope_type='AREA' AND area_id=?))");$s->execute([Auth::id(),$regionId,$parkId,$areaId]);return (int)$s->fetchColumn()>0;}public function scopesForUser(int $uid):array{$s=Database::pdo()->prepare('SELECT us.*,r.name region_name,p.name park_name,a.name area_name FROM user_scopes us LEFT JOIN regions r ON r.id=us.region_id LEFT JOIN parks p ON p.id=us.park_id LEFT JOIN areas a ON a.id=us.area_id WHERE us.user_id=? AND us.ended_at IS NULL ORDER BY us.scope_type');$s->execute([$uid]);return $s->fetchAll();}}
